93	  /* Process timer interrupt */
94	
95	  state = getreg32(TM1_ADDR + INTR_STATE_TIMER);
96	  state &= ~0x7;
97	  putreg32(state, TM1_ADDR + INTR_STATE_TIMER);
98	
99	  /* Ready for the next interrupt */
100	
101	  putreg32(cmp, TM1_ADDR + COUNTER_TIMER);
