126	  /* up_disable_irq(IRQ_SYSTIMER); */
127	
128	  putreg32(0, TM1_ADDR + CNTL_TIMER);
129	  putreg32(0, TM1_ADDR + INTR_STATE_TIMER);
130	  putreg32(0x1ff, TM1_ADDR + INTR_MASK_TIMER);
131	
132	  /* Initialize to a known state */
133	
134	  putreg32(cmp, TM1_ADDR + COUNTER_TIMER);
135	  putreg32(0, TM1_ADDR + LOAD_TIMER);
136	  putreg32(0, TM1_ADDR + MATCH1_TIMER);
137	
138	  /* Attach and enable the timer interrupt */
139	
140	  irq_attach(IRQ_SYSTIMER, (xcpt_t)moxart_timerisr, NULL);
141	  up_enable_irq(IRQ_SYSTIMER);
142	  ftintc010_set_trig_mode(IRQ_SYSTIMER, 1);
143	  ftintc010_set_trig_level(IRQ_SYSTIMER, 0);
144	
145	  /* Unmask IRQ */
146	
147	  tmp = getreg32(TM1_ADDR + INTR_MASK_TIMER);
148	  tmp &= ~TM1_MATCH1;
149	  putreg32(tmp, TM1_ADDR + INTR_MASK_TIMER);
150	
151	  tmp = getreg32(TM1_ADDR + CNTL_TIMER);
152	  tmp |= TM1_CLOCK | TM1_ENABLE;
153	  putreg32(tmp, TM1_ADDR + CNTL_TIMER);
154	}
