342	
343	static void rv1126b_uart_send(struct uart_dev_s *dev, int ch)
344	{
345	  struct rv1126b_uart_s *priv = (struct rv1126b_uart_s *)dev->priv;
346	  uint32_t base = priv->base;
347	
348	  /* Write the character to the transmit holding register */
349	
350	  putreg32((uint32_t)ch, UART_THR(base));
351	}
