353	/****************************************************************************
354	 * Name: rv1126b_uart_rxint
355	 *
356	 * Description:
357	 *   Enable or disable the RX interrupt.
358	 *
359	 ****************************************************************************/
360	
361	static void rv1126b_uart_rxint(struct uart_dev_s *dev, bool enable)
362	{
363	  struct rv1126b_uart_s *priv = (struct rv1126b_uart_s *)dev->priv;
364	  uint32_t base = priv->base;
365	  uint32_t regval;
366	
367	  regval = getreg32(UART_IER(base));
368	
369	  if (enable)
370	    {
371	      regval |= RV1126B_UART_IER_ERBFI;  /* Enable Received Data Available */
372	    }
373	  else
374	    {
375	      regval &= ~RV1126B_UART_IER_ERBFI;
376	    }
377	
378	  putreg32(regval, UART_IER(base));
379	}
