381	/****************************************************************************
382	 * Name: rv1126b_uart_txint
383	 *
384	 * Description:
385	 *   Enable or disable the TX interrupt.
386	 *
387	 ****************************************************************************/
388	
389	static void rv1126b_uart_txint(struct uart_dev_s *dev, bool enable)
390	{
391	  struct rv1126b_uart_s *priv = (struct rv1126b_uart_s *)dev->priv;
392	  uint32_t base = priv->base;
393	  uint32_t regval;
394	
395	  regval = getreg32(UART_IER(base));
396	
397	  if (enable)
398	    {
399	      regval |= RV1126B_UART_IER_ETBEI;  /* Enable THR Empty */
400	      putreg32(regval, UART_IER(base));
401	
402	      /* Prime transmission.  uart_xmitchars() may safely disable ETBEI
403	       * through this callback after the software TX buffer is drained.
404	       */
405	
406	      uart_xmitchars(dev);
407	    }
408	  else
409	    {
410	      regval &= ~RV1126B_UART_IER_ETBEI;
411	      putreg32(regval, UART_IER(base));
412	    }
413	}
