463	/****************************************************************************
464	 * Name: rv1126b_uart_interrupt
465	 *
466	 * Description:
467	 *   UART interrupt handler.  This is called when any UART interrupt occurs.
468	 *
469	 ****************************************************************************/
470	
471	static int rv1126b_uart_interrupt(int irq, void *context, void *arg)
472	{
473	  struct uart_dev_s *dev = (struct uart_dev_s *)arg;
474	
475	  (void)irq;
476	  (void)context;
477	  struct rv1126b_uart_s *priv = (struct rv1126b_uart_s *)dev->priv;
478	  uint32_t base = priv->base;
479	  uint32_t iir;
480	  uint32_t id;
481	
482	  /* Read the interrupt identification register */
483	
484	  iir = getreg32(UART_IIR(base));
485	
486	  /* Check if there is an interrupt pending */
487	
488	  if (iir & RV1126B_UART_IIR_NONE)
489	    {
490	      return OK;  /* No interrupt pending */
491	    }
492	
493	  id = iir & RV1126B_UART_IIR_ID_MASK;
494	
495	  /* Dispatch based on interrupt type */
496	
497	  switch (id)
498	    {
499	      case RV1126B_UART_IIR_RDA:    /* Received Data Available */
500	      case RV1126B_UART_IIR_CTI:    /* Character Timeout */
501	        {
502	          uart_recvchars(dev);
503	          break;
504	        }
505	
506	      case RV1126B_UART_IIR_THRE:   /* Transmit Holding Register Empty */
507	        {
508	          uart_xmitchars(dev);
509	          break;
510	        }
511	
512	      case RV1126B_UART_IIR_RLS:    /* Receiver Line Status */
513	        {
514	          /* Read LSR to clear the interrupt */
515	
516	          getreg32(UART_LSR(base));
517	          break;
518	        }
519	
520	      case RV1126B_UART_IIR_BUSY:   /* Busy Detect */
521	        {
522	          /* Read USR to clear the interrupt */
523	
524	          getreg32(UART_USR(base));
525	          break;
526	        }
527	
528	      default:
529	        break;
530	    }
531	
532	  return OK;
533	}
