539	/****************************************************************************
540	 * Name: riscv_earlyserialinit
541	 *
542	 * Description:
543	 *   Performs the low level UART initialization early in debug so that the
544	 *   serial console will be available during bootup.
545	 *
546	 ****************************************************************************/
547	
548	void riscv_earlyserialinit(void)
549	{
550	  /* The UART5 clock and pins were already configured in rv1126b_lowsetup().
551	   * Here we just need to setup the console UART with default parameters.
552	   */
553	
554	  g_console_port.isconsole = true;
555	  rv1126b_uart_setup(&g_console_port);
556	}
