558	/****************************************************************************
559	 * Name: riscv_serialinit
560	 *
561	 * Description:
562	 *   Register the UART driver as /dev/console and /dev/ttyS0.
563	 *
564	 ****************************************************************************/
565	
566	void riscv_serialinit(void)
567	{
568	  /* Register the console as /dev/console */
569	
570	  uart_register("/dev/console", &g_console_port);
571	
572	  /* Register the same UART as /dev/ttyS0 */
573	
574	  uart_register("/dev/ttyS0", &g_console_port);
575	}
