577	/****************************************************************************
578	 * Name: up_putc
579	 *
580	 * Description:
581	 *   Output one character to the console UART.
582	 *   This is used by the OS for debug output after the serial driver is
583	 *   initialized.
584	 *
585	 ****************************************************************************/
586	
587	void up_putc(int ch)
588	{
589	  struct rv1126b_uart_s *priv = (struct rv1126b_uart_s *)g_console_port.priv;
590	  uint32_t base = priv->base;
591	
592	  /* Wait until TX FIFO is not full */
593	
594	  while (!(getreg32(UART_USR(base)) & RV1126B_UART_USR_TFNF))
595	    {
596	    }
597	
598	  /* Write the character */
599	
600	  putreg32((uint32_t)ch, UART_THR(base));
601	}
